  @override Widget build(BuildContext context)=>MaterialApp(debugShowCheckedModeBanner:false, themeMode:dark?ThemeMode.dark:ThemeMode.light, theme:_theme(false), darkTheme:_theme(true), home:logged?HomePage(english:english,dark:dark,onLang:()=>setState(()=>english=!english),onTheme:()=>setState(()=>dark=!dark),onLogout:()async{final p=await SharedPreferences.getInstance();await p.setBool('logged',false);setState(()=>logged=false);}):LoginPage(english:english,onLogin:()=>setState(()=>logged=true)));
