class Signal { final String symbol,side,timeframe; final double score,entry,stop,tp; Signal(this.symbol,this.side,this.timeframe,this.score,this.entry,this.stop,this.tp); }

class HomePage extends StatefulWidget { final bool english,dark; final VoidCallback onLang,onTheme,onLogout; const HomePage({super.key,required this.english,required this.dark,required this.onLang,required this.onTheme,required this.onLogout}); @override State<HomePage> createState()=>_HomePageState(); }
class _HomePageState extends State<HomePage>{ bool loading=false; String timeframe='15m'; double capital=10000000; Signal? signal; String? status;
 final symbols=['BTCUSDT','ETHUSDT','SOLUSDT','XRPUSDT','DOGEUSDT','ADAUSDT','SUIUSDT','PEPEUSDT'];
 Future<List<dynamic>> getJson(String path,Map<String,String> q)async{final uri=Uri.parse('$apiBase$path').replace(queryParameters:q);final r=await http.get(uri).timeout(const Duration(seconds:8));if(r.statusCode!=200)throw Exception('HTTP ${r.statusCode}');return jsonDecode(r.body) as List<dynamic>;}
 Future<Map<String,dynamic>> depth(String s)async{final uri=Uri.parse('$apiBase/r/api/v1/depth').replace(queryParameters:{'symbol':s,'limit':'30'});final r=await http.get(uri).timeout(const Duration(seconds:8));if(r.statusCode!=200)throw Exception();return jsonDecode(r.body);}
 Future<void> scan()async{setState(()=>{loading=true,status=null,signal=null}); final found=<Signal>[]; for(final s in symbols){try{final t=await getJson('/r/api/v1/trades',{'symbol':s,'limit':'300'});if(t.length<30)continue;final prices=t.map((e)=>double.tryParse('${e is List?e[0]:e['price']}')??0).where((x)=>x>0).toList();if(prices.length<30)continue;final entry=prices.last, old=prices[prices.length~/3], change=(entry-old)/old*100;final d=await depth(s);double bid=0,ask=0;for(final x in (d['bids']??[]))bid+=double.parse('${x[1]}');for(final x in (d['asks']??[]))ask+=double.parse('${x[1]}');final imbalance=(bid+ask)==0?0:(bid-ask)/(bid+ask);final side=change>=0&&imbalance>=-0.15?'LONG':'SHORT';final score=(50+change.abs().clamp(0,20)*2+imbalance*25).clamp(0,100).toDouble();final risk=entry*0.006;final stop=side=='LONG'?entry-risk:entry+risk;final tp=side=='LONG'?entry+risk*2.5:entry-risk*2.5;if(score>=62)found.add(Signal(s,side,timeframe,score,entry,stop,tp));}catch(_){}}
 found.sort((a,b)=>b.score.compareTo(a.score));setState(()=>{loading=false;signal=found.isEmpty?null:found.first;status=found.isEmpty?(widget.english?'No valid setup found.':'سیگنال معتبر پیدا نشد.'):(widget.english?'Scan completed.':'اسکن بازار انجام شد.');}); }
 String n(double x)=>x.toStringAsFixed(x>=1000?2:6);
 @override Widget build(BuildContext c){final en=widget.english;return Scaffold(appBar:AppBar(title:Text(en?'Signal Scanner':'اسکنر سیگنال'),actions:[IconButton(onPressed:widget.onTheme,icon:Icon(widget.dark?Icons.light_mode:Icons.dark_mode)),IconButton(onPressed:widget.onLang,icon:const Icon(Icons.language)),IconButton(onPressed:widget.onLogout,icon:const Icon(Icons.logout))]),body:RefreshIndicator(onRefresh:scan,child:ListView(padding:const EdgeInsets.all(16),children:[Card(child:Padding(padding:const EdgeInsets.all(18),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(en?'Market scanner':'اسکن بازار',style:Theme.of(c).textTheme.titleLarge?.copyWith(fontWeight:FontWeight.bold)),const SizedBox(height:12),Row(children:[Expanded(child:DropdownButtonFormField<String>(value:timeframe,decoration:InputDecoration(labelText:en?'Timeframe':'تایم‌فریم'),items:['1m','5m','15m','1h'].map((x)=>DropdownMenuItem(value:x,child:Text(x))).toList(),onChanged:(v)=>setState(()=>timeframe=v!))),const SizedBox(width:12),Expanded(child:TextFormField(initialValue:'10000000',keyboardType:TextInputType.number,decoration:InputDecoration(labelText:en?'Capital (Toman)':'سرمایه (تومان)'),onChanged:(v)=>capital=double.tryParse(v.replaceAll(',',''))??capital))]),const SizedBox(height:16),SizedBox(width:double.infinity,height:52,child:FilledButton.icon(onPressed:loading?null:scan,icon:loading?const SizedBox(width:20,height:20,child:CircularProgressIndicator(strokeWidth:2)):const Icon(Icons.radar),label:Text(loading?(en?'Scanning...':'در حال اسکن...'):(en?'Scan best opportunity':'پیدا کردن بهترین فرصت'))))])),const SizedBox(height:14),if(status!=null&&!loading)Card(child:ListTile(leading:Icon(signal==null?Icons.block:Icons.check_circle),title:Text(status!))),if(signal!=null)_SignalCard(signal:signal!,en:en),const SizedBox(height:10),Card(child:const ListTile(leading:Icon(Icons.shield_outlined),title:Text('Signal-only mode'),subtitle:Text('No orders are sent to the exchange.')))])));
}
