class _SignalCard extends StatelessWidget{final Signal signal;final bool en;const _SignalCard({required this.signal,required this.en});String n(double x)=>x.toStringAsFixed(6);@override Widget build(BuildContext c)=>Card(child:Padding(padding:const EdgeInsets.all(20),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Row(mainAxisAlignment:MainAxisAlignment.spaceBetween,children:[Text(signal.symbol,style:Theme.of(c).textTheme.headlineSmall?.copyWith(fontWeight:FontWeight.bold)),Chip(label:Text(signal.side))]),Text('${en?'Timeframe':'تایم‌فریم'}: ${signal.timeframe}'),const Divider(height:28),_r(c,en?'Signal score':'امتیاز سیگنال','${signal.score.toStringAsFixed(0)}/100'),_r(c,en?'Entry':'نقطه ورود',n(signal.entry)),_r(c,en?'Stop Loss':'حد ضرر',n(signal.stop)),_r(c,en?'Take Profit':'حد سود',n(signal.tp)),_r(c,en?'Risk/Reward':'ریسک به سود','1 : 2.5')])));Widget _r(BuildContext c,String a,String b)=>Padding(padding:const EdgeInsets.symmetric(vertical:6),child:Row(mainAxisAlignment:MainAxisAlignment.spaceBetween,children:[Text(a),Text(b,style:const TextStyle(fontWeight:FontWeight.bold))]));}
